import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?
    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        window = UIWindow(frame: UIScreen.main.bounds)
        window?.rootViewController = UIViewController()
        window?.makeKeyAndVisible()
        return true
    }
}

import XCTest

final class TapTests: XCTestCase {
    func attachScreenshot(_ app: XCUIApplication, name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot())
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    func testOpenProfileAndFollow() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 10) {
            openButton.tap()
        }

        let bsky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        XCTAssertTrue(bsky.waitForState(.runningForeground, timeout: 20), "Bluesky did not come to foreground")

        let profileLoaded = bsky.staticTexts["newfriend.test"].waitForExistence(timeout: 30)
            || bsky.staticTexts["newfriend"].waitForExistence(timeout: 5)
        attachScreenshot(bsky, name: "after-open")
        XCTAssertTrue(profileLoaded, "Profile screen did not load")

        let followingButton = bsky.buttons.matching(NSPredicate(format: "label == 'Following'")).firstMatch
        let followButton = bsky.buttons.matching(NSPredicate(format: "label == 'Follow'")).firstMatch

        if followButton.waitForExistence(timeout: 5) {
            followButton.tap()
            XCTAssertTrue(followingButton.waitForExistence(timeout: 15), "Follow tap did not switch to Following")
        } else {
            XCTAssertTrue(followingButton.waitForExistence(timeout: 10), "Following button not found")
        }

        attachScreenshot(bsky, name: "final")
        bsky.activate()
    }
}

