import XCTest

final class TapTests: XCTestCase {
    func testDismissDialogsAndVerify() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        for i in 0..<6 {
            let openButton = springboard.buttons["Open"]
            if openButton.waitForExistence(timeout: 3) {
                print("tapping Open dialog #\(i)")
                openButton.tap()
                Thread.sleep(forTimeInterval: 1.5)
            } else {
                break
            }
        }

        let bsky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        XCTAssertTrue(bsky.wait(for: .runningForeground, timeout: 20))
        bsky.activate()
        Thread.sleep(forTimeInterval: 2)

        for (i, b) in bsky.buttons.allElementsBoundByIndex.enumerated() {
            print("BUTTON[\(i)] label='\(b.label)' identifier='\(b.identifier)'")
        }

        let profileLoaded = bsky.staticTexts["newfriend.test"].waitForExistence(timeout: 30)
        print("profileLoaded=\(profileLoaded)")

        let followButtons = bsky.buttons.matching(NSPredicate(format: "label == 'Follow'"))
        let followingButtons = bsky.buttons.matching(NSPredicate(format: "label CONTAINS 'Following'"))
        print("followButtonCount=\(followButtons.count) followingButtonCount=\(followingButtons.count)")

        if followButtons.count > 0 {
            followButtons.firstMatch.tap()
            XCTAssertTrue(followingButtons.firstMatch.waitForExistence(timeout: 15), "Follow tap did not switch to Following")
        } else {
            XCTAssertTrue(followingButtons.count > 0, "Following button not found")
        }

        let attachment = XCTAttachment(screenshot: bsky.screenshot())
        attachment.name = "final"
        attachment.lifetime = .keepAlways
        add(attachment)
        bsky.activate()
    }
}
